---@field TextDescribe                  	UnityEngine.RectTransform               	@ 8    
local BeginnerAssembleTaskCellNode = Class("BeginnerAssembleTaskCellNode")

function BeginnerAssembleTaskCellNode:__init()
    self.btnActionJump = nil
    self.btnActionGet  = nil
end

function BeginnerAssembleTaskCellNode:__delete()
    self.btnActionJump = nil
    self.btnActionGet  = nil
    self.controller    = nil
end

---SetBtnCallBackJump
---设置单击回调函数(跳转)
function BeginnerAssembleTaskCellNode:SetBtnCallBackJump(cb)
    self.btnActionJump = cb
end

---SetBtnCallBackGet
---设置单击回调函数(领取)
function BeginnerAssembleTaskCellNode:SetBtnCallBackGet(cb)
    self.btnActionGet = cb
end

function BeginnerAssembleTaskCellNode:GetCellDt()
    return checkTable(self.cellDt)
end

function BeginnerAssembleTaskCellNode:IsHasDrawn()
    return checkInt(self:GetCellDt().hasDrawn) == 1
end

function BeginnerAssembleTaskCellNode:IsCanJump()
    return checkInt(self:GetCellDt().taskVo.openType) ~= 0
end

function BeginnerAssembleTaskCellNode:IsCanDrawn()
    return (checkNumber(self:GetCellDt().progress) >= checkNumber(self:GetCellDt().taskContentNum)) and not self:IsHasDrawn()
end

function BeginnerAssembleTaskCellNode:Awake()
    SetButtonAction(self.FontStyleButton, function()
        if self:IsCanDrawn() then
            if type(self.btnActionGet) == 'function' then
                self.btnActionGet()
            end
        elseif self:IsCanJump() then
            if type(self.btnActionJump) == 'function' then
                self.btnActionJump()
            end
        end
    end)
end

function BeginnerAssembleTaskCellNode:FreshBaseUI(data, isSub)
    isSub = checkBool(isSub)
    self.cellDt = checkTable(data)
    CfUtils.SetActive(self.CommonGoodsList.transform.parent:Find("ImgMainTask"), false)
    local isHasDrawn = self:IsHasDrawn()
    local isCanDrawn = self:IsCanDrawn()
    local isCanJump  = self:IsCanJump()
    if data.taskVo then
        CfUtils.FillText(self.TextDescribe, data.taskVo.descr)
        UICommonUtils.FillCommonGoodsListLight(self.CommonGoodsList, parse_rewards(data.taskVo.rewardId, data.taskVo.rewardNum), false, false, true, false, false)
        self.ProgressBar.value = data.progress / data.taskContentNum
        self.TextProgress.text = string.format("%s/%s", data.progress, data.taskContentNum)
        local isMainTask  = checkNumber(data.taskVo.isMainTask) == 1
        CfUtils.SetActive(self.CommonGoodsList.transform.parent:Find("ImgMainTask"), not isSub)
    end

    KTool.SetActive(self.FontStyleButton, (isCanJump and not isHasDrawn) or isCanDrawn)
    KTool.SetActive(self.TextUnderWay, not isCanJump and not isHasDrawn and not isCanDrawn)
    KTool.SetActive(self.TextComplete, isHasDrawn)
    KTool.SetActive(self.CanGet, isCanDrawn)

    if self.UIFX_BeginnerEventDialogContainer then
        KTool.SetActive(self.UIFX_BeginnerEventDialogContainer, isCanDrawn and not isHasDrawn)
    end

    --CfUtils.SetScale(self.controller.gameObject, isMainTask and Vector3(1.05, 1.05, 0) or Vector3.one)


    if not isHasDrawn then
        if isCanDrawn then
            self.FontStyleButton:ResetFontStyle("B12", localize("领取"))
        elseif isCanJump then
            self.FontStyleButton:ResetFontStyle("B13", localize("前往"))
        end
    end
end

function BeginnerAssembleTaskCellNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return BeginnerAssembleTaskCellNode